describe('Password Confirmation Validation', () => {
    beforeEach(() => {
        cy.visit('/signup'); // Adjust the URL to your signup page
    });

    it('should show no error when passwords match', () => {
        cy.get('input[name="password"]').type('Password123!');
        cy.get('input[name="confirmPassword"]').type('Password123!');
        cy.get('input[name="confirmPassword"]').blur(); // Trigger validation
        cy.get('.error-message').should('not.exist'); // Adjust selector for error message
    });

    it('should show an error when passwords do not match', () => {
        cy.get('input[name="password"]').type('Password123!');
        cy.get('input[name="confirmPassword"]').type('DifferentPassword!');
        cy.get('input[name="confirmPassword"]').blur(); // Trigger validation
        cy.get('.error-message').should('contain', 'Passwords do not match'); // Adjust selector and message
    });
});
